; --- διαστάσεις εξωτερικών δομών, 4 θέσεις ανά δομή ---
; struct_dims + kind*8 + size*2 -> (w bytes, h)· 0,0 = δεν υπάρχει
struct_dims:
    db   4, 16,  8, 32, 12, 48,  0,  0   ; solar — ηλιακό πάνελ — 3 μεγέθη
    db   4, 16,  8, 32, 12, 48,  0,  0   ; turbine — ανεμογεννήτρια
    db   4, 16,  8, 32, 12, 48,  0,  0   ; collector — συσσωρευτής ενέργειας
    db   4, 16,  8, 32, 12, 48,  0,  0   ; extractor — αντλία νερού
    db  16, 64,  0,  0,  0,  0,  0,  0   ; mine — ορυχείο — ένα μέγεθος
    db   8, 32,  0,  0,  0,  0,  0,  0   ; airlock — αεροθάλαμος — ένα μέγεθος
    db  16, 64,  0,  0,  0,  0,  0,  0   ; pad — πλατφόρμα — ΑΔΙΑΦΑΝΗΣ
    db   8, 32,  0,  0,  0,  0,  0,  0   ; ship — σκάφος — κάτοψη
    db   8, 32,  0,  0,  0,  0,  0,  0   ; crates — τα κιβώτια του σκάφους που γκρεμίστηκε

machine_count:
    db 1,4,8
    ; s, m, l

; --- θέσεις μηχανημάτων, 8 ανά μέγεθος (255 = κενή) ---
; machine_slots + size*MACH_SLOTS*2 + slot*2 -> (x bytes, y)
machine_slots:
    db   5, 28   ; s θέση 0
    db 255,255   ; s θέση 1
    db 255,255   ; s θέση 2
    db 255,255   ; s θέση 3
    db 255,255   ; s θέση 4
    db 255,255   ; s θέση 5
    db 255,255   ; s θέση 6
    db 255,255   ; s θέση 7
    db   5, 30   ; m θέση 0
    db  12, 30   ; m θέση 1
    db   5, 54   ; m θέση 2
    db  12, 54   ; m θέση 3
    db 255,255   ; m θέση 4
    db 255,255   ; m θέση 5
    db 255,255   ; m θέση 6
    db 255,255   ; m θέση 7
    db  13, 15   ; l θέση 0
    db   6, 26   ; l θέση 1
    db   3, 53   ; l θέση 2
    db   6, 80   ; l θέση 3
    db  12, 91   ; l θέση 4
    db  19, 80   ; l θέση 5
    db  22, 53   ; l θέση 6
    db  19, 26   ; l θέση 7

machine_rules:
    db 1,7,7,7,7,7,7,7,7,7,7,7
    ; oxygen, iron, bioplastic, weapons, processors, robots, food, spares, medical, vitromeat, beds, medstore

; --- ποια μηχανήματα δέχεται κάθε τύπος δωματίου ---
; room_machines + type*2 -> bitmask 12 bit (little-endian)
; bit N = το μηχάνημα N της λίστας machines
room_machines:
    dw #0000   ;  0 empty      —
    dw #0010   ;  1 control    processors
    dw #0000   ;  2 quarters   —
    dw #0040   ;  3 canteen    food
    dw #0001   ;  4 oxygen     oxygen
    dw #0000   ;  5 greenhouse —
    dw #0000   ;  6 storage    —
    dw #0000   ;  7 airlock    —
    dw #00AE   ;  8 factory    iron, bioplastic, weapons, robots, spares
    dw #0310   ;  9 lab        processors, medical, vitromeat
    dw #0C00   ; 10 medbay     beds, medstore
    dw #0000   ; 11 lounge     —

; --- θέσεις εικονιδίου/πληρότητας από το ΚΕΝΤΡΟ του θόλου ---
; interior_ofs + size*2 -> (icon dx bytes, icon dy) από το κέντρο
interior_ofs:
    db 253,238   ; s
    db 252,220   ; m
    db 251,246   ; l

